    for key in ('Fine','Coarse','Mouths'):g.socket(key,'NodeSocketGeometry')
    for key in ('Fine Rows','Fine Radial','Coarse Rows','Coarse Radial'):g.socket(key,'NodeSocketInt')
    g.socket('Input Valid','NodeSocketBool')
    g.socket('Geometry','NodeSocketGeometry','OUTPUT');g.socket('Valid','NodeSocketBool','OUTPUT')
