    chart,row,col=[g.math('ROUND',x) for x in g.separate(c.named(g,'st_cq_key','FLOAT_VECTOR'))]
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    keyed=c._store(g,coarse,'_gp_position',g.position(),'FLOAT_VECTOR')
    keyed=g.setpos(keyed,g.xyz(chart,row,col))

    def sample(side,u,v):
        x=minimum(maximum(u,0.),1.)*N;y=minimum(maximum(v,0.),1.)*M
        lo=g.math('FLOOR',x);bottom=g.math('FLOOR',y)
        hi=minimum(lo+1.,N);top=minimum(bottom+1.,M);a=x-lo;b=y-bottom
        position=[0.,0.];matched=1.
