            g.bind(keyed,near.inputs['Geometry']);g.bind(wanted,near.inputs['Sample Position'])
            at=near.outputs['Index'];found=c._vec(g,c._sample(g,keyed,g.position(),at,'FLOAT_VECTOR'))
