    valid=valid*c._stat(g,rim,parameters)
    here=c._vec(g,g.position())
    distance0=c._length(g,c._sub(here,c._vec(g,c._sample(g,rim,g.position(),previous,'FLOAT_VECTOR'))))
    distance1=c._length(g,c._sub(here,c._vec(g,c._sample(g,rim,g.position(),following,'FLOAT_VECTOR'))))
    # At an end, only its existing neighbor contributes. The actual full
