    small=choose(equal(row,0.),distance1,choose(equal(row,n),distance0,minimum(distance0,distance1)))
    rim=c._store(g,rim,'_gd_depth',depth)
    rim=c._store(g,rim,'_gd_delta',g.xyz(*c._sub(here,outer)),'FLOAT_VECTOR')
    rim=c._store(g,rim,'_gd_first',minimum(depth/m,EDGE_FACTOR*small))
    rim=c._store(g,rim,'_gd_ok',ok0*ok1*g.math('GREATER_THAN',depth,1e-8)*g.math('GREATER_THAN',small,1e-8),'BOOLEAN')
    for _ in range(TAPER_PASSES):
        first=c.named(g,'_gd_first')
        lower=c._read(g,rim,'_gd_first',previous)+NEIGHBOR_TAPER*distance0
        # Match the reference's forward then backward pass, including use of
