    fixed=c.named(g,'st_cq_fixed','BOOLEAN');selected=band*(1.-fixed)
    valid=valid*c._stat(g,fine,choose(selected,matched,True,'BOOLEAN'))
    xy=c._pick(g,selected,placed,c._vec(g,g.position()))
    z=g.separate(c._sample(g,fine,g.position(),index,'FLOAT_VECTOR'))[2]
    result=g.setpos(base.outputs['Geometry'],g.xyz(*xy,z))
    g.bind(original.boundary._empty(g,result,valid),out.inputs['Geometry']);g.bind(valid,out.inputs['Valid'])
